def cappedError (P : PaperProofs.Paid.Parameters) (m : ℕ) : ℚ :=
  ∑ state : WalkCell (m + 1), P.walkDistribution (m + 1) true P.certificate.Q state *
    if state.val < m + 1 then 1 else if state.val = m + 1 then 1 / 2 else 0

PaperProofs.Paid.Parameters.CalibrationM.full_declaration_source:
def CalibrationMarksClaims (P : PaperProofs.Paid.Parameters) : Prop :=
  ∀ (stage : P.sharedInstance.Stage) (level : Fin (P.certificate.M + 1)),
    P.calibratedMenuSeedLaw.map (fun seed => (seed.2 stage level, seed.1 stage)) = P.calibrationSeedLaw level.val

PaperProofs.Paid.Parameters.buildCachedF.full_declaration_source:
def buildCachedFrontend (P : PaperProofs.Paid.Parameters) (fee : ℚ) : CachedFrontend :=
  let endpoints := P.endpointCache
  let calibration := P.calibrationWeightCache endpoints
  let state := P.cachedMultiplierSearch endpoints fee (P.bisectionBudget fee)
  ⟨endpoints, calibration, state⟩

PaperProofs.Paid.Parameters.SharedPoolSu.full_declaration_source:
def SharedPoolSubproblemRank : Prop :=
  ∀ n k : ℕ,
    errorRank (freshInstance n k).compatibility (freshInstance n k).tools =
      if n ≤ k then ⊤ else ((k + 1 : ℕ) : ℕ∞)

